WITH cleaned AS (SELECT *, DATEDIFF(ends_on, starts_on) AS days_starts_on_to_ends_on, COALESCE(channel, 'NONE') AS channel_clean FROM promotions WHERE ends_on > DATE '2023-08-09') SELECT *, MIN(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_min_discount_pct, AVG(days_starts_on_to_ends_on) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS days_starts_on_to_ends_on_avg_6_prior, LAG(days_starts_on_to_ends_on, 1) OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS prev_days_starts_on_to_ends_on, AVG(days_starts_on_to_ends_on) OVER (PARTITION BY channel ORDER BY ends_on, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS days_starts_on_to_ends_on_avg_6, SUM(discount_pct) OVER (PARTITION BY promo_code, channel ORDER BY days_starts_on_to_ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct FROM cleaned WHERE promo_code IN ('BUNDLE', 'SPRING10', 'WELCOME5');
